/**
 * Reproduction of CPython's `repr()` for floating point numbers.
 *
 * CPython formats a float with `PyOS_double_to_string(v, 'r', 0, ADD_DOT_0)`:
 * the shortest digit string that round-trips is produced, then rendered in
 * positional notation unless the decimal point position `decpt` satisfies
 * `decpt <= -4 || decpt > 16`, in which case exponential notation is used with
 * an exponent of at least two digits and an explicit sign.
 */

/** Shortest round-tripping digits of a finite non-zero magnitude. */
function shortestDigits(magnitude) {
  const m = /^(\d)(?:\.(\d+))?e([+-]\d+)$/.exec(magnitude.toExponential());
  return { digits: m[1] + (m[2] || ''), decpt: Number(m[3]) + 1 };
}

function exponential(digits, decpt) {
  const exp = decpt - 1;
  const frac = digits.slice(1);
  const sign = exp < 0 ? '-' : '+';
  return `${digits[0]}${frac ? '.' + frac : ''}e${sign}${String(Math.abs(exp)).padStart(2, '0')}`;
}

function positional(digits, decpt) {
  if (decpt <= 0) return `0.${'0'.repeat(-decpt)}${digits}`;
  if (decpt >= digits.length) return `${digits}${'0'.repeat(decpt - digits.length)}.0`;
  return `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
}

/** `repr(float)` — e.g. 1.0 -> "1.0", 1e16 -> "1e+16", 1e-7 -> "1e-07". */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  const negative = value < 0 || Object.is(value, -0);
  const magnitude = Math.abs(value);
  if (magnitude === 0) return negative ? '-0.0' : '0.0';

  const { digits, decpt } = shortestDigits(magnitude);
  const body = decpt <= -4 || decpt > 16
    ? exponential(digits, decpt)
    : positional(digits, decpt);
  return negative ? `-${body}` : body;
}

