/**
 * Python `str` semantics that JavaScript strings do not share out of the box:
 * code point iteration, `len()`, ordering and `repr()`.
 */

/** Python iterates strings by code point, not by UTF-16 unit. */
export function codePoints(text) {
  return Array.from(text);
}

/** `len(str)` counts code points. */
export function strLen(text) {
  let count = 0;
  for (const _ of text) count += 1;
  return count;
}

/**
 * `<` on Python strings compares code points. JavaScript's `<` compares UTF-16
 * units, which orders astral characters before U+E000..U+FFFF instead of after.
 */
export function strCompare(a, b) {
  const left = codePoints(a);
  const right = codePoints(b);
  const shared = Math.min(left.length, right.length);
  for (let i = 0; i < shared; i += 1) {
    const x = left[i].codePointAt(0);
    const y = right[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  return left.length - right.length;
}

export function sortStrings(values) {
  return [...values].sort(strCompare);
}

// `str.isprintable()`: false for the Unicode "Other" (C*) and "Separator" (Z*)
// categories, with ASCII space as the sole exception.
const NON_PRINTABLE = /^[\p{C}\p{Z}]$/u;

function isPrintable(character) {
  return character === ' ' || !NON_PRINTABLE.test(character);
}

function hexEscape(codePoint) {
  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * `repr(str)`. Single quotes are preferred; double quotes are used when the
 * string contains an apostrophe but no double quote.
 */
export function strRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const character of text) {
    const codePoint = character.codePointAt(0);
    if (character === quote || character === '\\') out += `\\${character}`;
    else if (character === '\t') out += '\\t';
    else if (character === '\n') out += '\\n';
    else if (character === '\r') out += '\\r';
