/**
 * The Python value model used throughout the validator.
 *
 * Python distinguishes `int` from `float`, keeps `dict` insertion order and has
 * unbounded integers, none of which survive a plain `JSON.parse`. Values are
 * therefore represented as:
 *
 *   None    -> null            int   -> BigInt
 *   bool    -> boolean         float -> number
 *   str     -> string          list  -> Array
 *   dict    -> Map (string keys, insertion ordered)
 */

export const isNone = (value) => value === null;
export const isBool = (value) => typeof value === 'boolean';
export const isInt = (value) => typeof value === 'bigint';
export const isFloat = (value) => typeof value === 'number';
export const isStr = (value) => typeof value === 'string';
export const isList = (value) => Array.isArray(value);
export const isDict = (value) => value instanceof Map;
export const isNumber = (value) => isInt(value) || isFloat(value);

/** Widen an int to a float, the way Python does in mixed arithmetic. */
export const toFloat = (value) => (isInt(value) ? Number(value) : value);

/** True when a number has no fractional part — `float.is_integer()`. */
export function isIntegral(value) {
  if (isInt(value)) return true;
  return Number.isFinite(value) && Number.isInteger(value);
}

/**
 * `_utils.unbool` maps the two booleans onto sentinels so that `True` never
 * compares equal to `1` and `False` never to `0`.
 */
const TRUE_SENTINEL = Symbol('True');
const FALSE_SENTINEL = Symbol('False');

export function unbool(value) {
  if (value === true) return TRUE_SENTINEL;
  if (value === false) return FALSE_SENTINEL;
  return value;
}

/**
 * `_utils.equal` — structural equality that treats ints and floats of the same
 * value as equal but keeps booleans distinct from numbers.
 */
export function equal(one, two) {
  if (isStr(one) || isStr(two)) return one === two;
  if (isList(one) && isList(two)) return sequenceEqual(one, two);
  if (isDict(one) && isDict(two)) return mappingEqual(one, two);
  const left = unbool(one);
  const right = unbool(two);
  if (typeof left === 'symbol' || typeof right === 'symbol') return left === right;
  if (isNumber(left) && isNumber(right)) return numbersEqual(left, right);
  return left === right;
}

function numbersEqual(one, two) {
  if (isInt(one) && isInt(two)) return one === two;
  // `==` between BigInt and Number is an exact mathematical comparison.
  // eslint-disable-next-line eqeqeq
  return one == two;
}

function sequenceEqual(one, two) {
  if (one.length !== two.length) return false;
  return one.every((item, index) => equal(item, two[index]));
}

function mappingEqual(one, two) {
  if (one.size !== two.size) return false;
  for (const [key, value] of one) {
    if (!two.has(key) || !equal(value, two.get(key))) return false;
  }
  return true;
}

/** `_utils.uniq` — whether every element of a list is distinct. */
export function uniq(container) {
  for (let i = 0; i < container.length; i += 1) {
    for (let j = i + 1; j < container.length; j += 1) {
      if (equal(container[i], container[j])) return false;
    }
  }
  return true;
}

/** Lift a plain `JSON.parse`-shaped value (used for the bundled metaschemas). */
export function fromPlain(value) {
  if (value === null) return null;
  if (Array.isArray(value)) return value.map(fromPlain);
  if (typeof value === 'object') {
    const map = new Map();
    for (const key of Object.keys(value)) map.set(key, fromPlain(value[key]));
    return map;
  }
  if (typeof value === 'number' && Number.isInteger(value)) return BigInt(value);
  return value;
}

