  if (isStr(value)) return strRepr(value);
  if (isList(value)) return `[${value.map(repr).join(', ')}]`;
  if (isDict(value)) {
    const entries = [];
    for (const [key, item] of value) entries.push(`${repr(key)}: ${repr(item)}`);
    return `{${entries.join(', ')}}`;
  }
  return String(value);
}

