/**
 * `json.loads` as CPython implements it, producing values in the Python model.
 *
 * The differences from `JSON.parse` that matter here: integers without a
 * fraction or exponent become unbounded `int`s, `NaN`/`Infinity`/`-Infinity`
 * are accepted, objects keep insertion order, and the error messages carry
 * CPython's wording.
 */

const WHITESPACE = new Set([' ', '\t', '\n', '\r']);
const NUMBER_RE = /^(-?(?:0|[1-9]\d*))(\.\d+)?([eE][-+]?\d+)?/;
const ESCAPES = new Map([
  ['"', '"'], ['\\', '\\'], ['/', '/'], ['b', '\b'],
  ['f', '\f'], ['n', '\n'], ['r', '\r'], ['t', '\t'],
]);

export class JSONDecodeError extends Error {
  constructor(message, text, position) {
    const before = text.slice(0, position);
    const line = before.split('\n').length;
    const column = position - before.lastIndexOf('\n');
    super(`${message}: line ${line} column ${column} (char ${position})`);
    this.name = 'json.decoder.JSONDecodeError';
    this.position = position;
  }
}

class Decoder {
  constructor(text) {
    this.text = text;
    this.at = 0;
  }

  fail(message, position = this.at) {
    throw new JSONDecodeError(message, this.text, position);
  }

  skipWhitespace() {
    while (this.at < this.text.length && WHITESPACE.has(this.text[this.at])) this.at += 1;
  }

  literal(word) {
    return this.text.startsWith(word, this.at) && (this.at += word.length) >= 0;
  }

  decode() {
    this.skipWhitespace();
    const value = this.value();
    this.skipWhitespace();
    if (this.at !== this.text.length) this.fail('Extra data');
    return value;
  }

  value() {
    if (this.at >= this.text.length) this.fail('Expecting value');
    const char = this.text[this.at];
    if (char === '"') return this.string();
    if (char === '{') return this.object();
    if (char === '[') return this.array();
    if (this.literal('null')) return null;
    if (this.literal('true')) return true;
    if (this.literal('false')) return false;
    if (this.literal('NaN')) return NaN;
    if (this.literal('Infinity')) return Infinity;
    if (this.literal('-Infinity')) return -Infinity;
    return this.number();
  }

  number() {
    const match = NUMBER_RE.exec(this.text.slice(this.at));
    if (!match) this.fail('Expecting value');
    this.at += match[0].length;
    const [, integer, fraction, exponent] = match;
    if (fraction || exponent) return Number(match[0]);
    return BigInt(integer);
  }

  string() {
    const start = this.at;
    this.at += 1;
    let out = '';
    for (;;) {
      if (this.at >= this.text.length) this.fail('Unterminated string starting at', start);
      const char = this.text[this.at];
      if (char === '"') {
        this.at += 1;
        return out;
      }
      if (char === '\\') {
        out += this.escape();
        continue;
      }
      if (char.codePointAt(0) < 0x20) this.fail('Invalid control character at');
      out += char;
      this.at += 1;
    }
  }

  escape() {
    this.at += 1;
    const char = this.text[this.at];
    if (char === undefined) this.fail('Unterminated string starting at');
    if (char !== 'u') {
      const simple = ESCAPES.get(char);
      if (simple === undefined) this.fail(`Invalid \\escape: ${JSON.stringify(char)}`);
      this.at += 1;
      return simple;
    }
    let unit = this.hex4();
    // A high surrogate followed by a low surrogate forms one code point.
    if (unit >= 0xd800 && unit <= 0xdbff && this.text.startsWith('\\u', this.at)) {
      const resume = this.at;
      this.at += 2;
      const low = this.hex4();
      if (low >= 0xdc00 && low <= 0xdfff) unit = 0x10000 + ((unit - 0xd800) << 10) + (low - 0xdc00);
      else this.at = resume;
    }
    return String.fromCodePoint(unit);
  }

  hex4() {
    const digits = this.text.slice(this.at + 1, this.at + 5);
    if (!/^[0-9a-fA-F]{4}$/.test(digits)) this.fail('Invalid \\uXXXX escape', this.at - 1);
    this.at += 5;
    return parseInt(digits, 16);
  }

  object() {
    const map = new Map();
    this.at += 1;
    this.skipWhitespace();
    if (this.text[this.at] === '}') {
      this.at += 1;
      return map;
    }
    for (;;) {
      this.skipWhitespace();
      if (this.text[this.at] !== '"') this.fail("Expecting property name enclosed in double quotes");
      const key = this.string();
      this.skipWhitespace();
      if (this.text[this.at] !== ':') this.fail("Expecting ':' delimiter");
      this.at += 1;
      this.skipWhitespace();
      map.set(key, this.value());
      this.skipWhitespace();
      const char = this.text[this.at];
      if (char === '}') {
        this.at += 1;
        return map;
      }
      if (char !== ',') this.fail("Expecting ',' delimiter");
      this.at += 1;
    }
  }

  array() {
    const items = [];
    this.at += 1;
    this.skipWhitespace();
    if (this.text[this.at] === ']') {
      this.at += 1;
      return items;
    }
    for (;;) {
      this.skipWhitespace();
      items.push(this.value());
      this.skipWhitespace();
      const char = this.text[this.at];
      if (char === ']') {
        this.at += 1;
        return items;
      }
      if (char !== ',') this.fail("Expecting ',' delimiter");
      this.at += 1;
    }
  }
}

export function loads(text) {
  return new Decoder(text).decode();
}

