 *   - Named groups are spelled `(?P<name>...)` and `(?P=name)`.
 *   - `\A` and `\Z` anchor to the very start / end of the subject.
 *   - Without `re.MULTILINE`, `$` also matches just before a trailing newline.
 *   - `(?#...)` introduces a comment group.
 *
 * Patterns are compiled with the `u` flag when possible, so that quantifiers and
 * `.` count code points as Python does; patterns that `u` rejects (a bare `{`,
 * an identity escape such as `\%`, ...) fall back to a unit-based compile.
 */

const UNICODE_CLASSES = new Map([
  ['d', { inside: '\\p{Nd}', outside: '\\p{Nd}' }],
  ['D', { inside: '\\P{Nd}', outside: '\\P{Nd}' }],
  ['w', { inside: '\\p{L}\\p{Nd}\\p{Nl}\\p{No}_', outside: '[\\p{L}\\p{Nd}\\p{Nl}\\p{No}_]' }],
  ['W', { inside: '\\W', outside: '[^\\p{L}\\p{Nd}\\p{Nl}\\p{No}_]' }],
  ['s', { inside: '\\s\\u001c-\\u001f\\u0085', outside: '[\\s\\u001c-\\u001f\\u0085]' }],
  ['S', { inside: '\\S', outside: '[^\\s\\u001c-\\u001f\\u0085]' }],
