const INLINE_FLAGS = /^\(\?([aiLmsux]+)\)/;

/** Pull leading `(?imsx)` groups off the pattern, mapping them onto JS flags. */
function extractInlineFlags(pattern) {
  let flags = '';
  let rest = pattern;
  for (;;) {
    const match = INLINE_FLAGS.exec(rest);
    if (!match) return { flags, rest };
    for (const letter of match[1]) {
      if ('ims'.includes(letter) && !flags.includes(letter)) flags += letter;
    }
    rest = rest.slice(match[0].length);
  }
}

function translate(pattern, { unicode, multiline }) {
  let out = '';
  let index = 0;
  let inClass = false;

  while (index < pattern.length) {
    const char = pattern[index];

    if (char === '\\') {
      const next = pattern[index + 1];
      index += 2;
      if (next === undefined) {
        out += '\\';
      } else if (next === 'A' && !inClass) {
        out += '^';
      } else if (next === 'Z' && !inClass) {
        out += '$';
      } else if (unicode && UNICODE_CLASSES.has(next)) {
