/**
 * `jsonschema.exceptions` — the error objects plus `best_match`, which decides
 * which of the collected errors `validate()` actually raises.
 */

export class ValidationError extends Error {
  constructor(message, { validator, context = [] } = {}) {
    super(message);
    this.name = 'ValidationError';
    this.pyMessage = message;
    this.validator = validator;
    this.path = [];
    this.context = context;
  }

  /** `_set()` never overwrites a keyword the producing validator chose itself. */
  setValidator(keyword) {
    if (this.validator === undefined) this.validator = keyword;
  }
}

export class SchemaError extends Error {
  constructor(message) {
    super(message);
    this.name = 'SchemaError';
    this.pyMessage = message;
  }
}

export class UnresolvableRefError extends Error {
  constructor(ref) {
    super(`Unresolvable: ${ref}`);
    this.name = 'Unresolvable';
    this.ref = ref;
  }
}

// `anyOf` / `oneOf` report the failure of a whole branch, so a sibling keyword's
// error is a more useful match than theirs.
const WEAK_MATCHES = new Set(['anyOf', 'oneOf']);
const STRONG_MATCHES = new Set();

/**
 * `by_relevance()` as an ordered tuple: shallower paths first, then the path
 * itself, then whether the keyword is a strong signal. Larger is "better".
 */
function relevance(error) {
  return [
    -error.path.length,
    error.path,
    !WEAK_MATCHES.has(error.validator),
    STRONG_MATCHES.has(error.validator),
  ];
}

function comparePathElements(left, right) {
  if (typeof left === typeof right) return left < right ? -1 : left > right ? 1 : 0;
  // Python would raise TypeError here; keep a deterministic order instead.
  return typeof left === 'bigint' ? -1 : 1;
}

function comparePaths(left, right) {
  const shared = Math.min(left.length, right.length);
  for (let i = 0; i < shared; i += 1) {
    const ordering = comparePathElements(left[i], right[i]);
    if (ordering !== 0) return ordering;
  }
  return left.length - right.length;
}

function compareRelevance(left, right) {
  const a = relevance(left);
  const b = relevance(right);
  if (a[0] !== b[0]) return a[0] < b[0] ? -1 : 1;
  const byPath = comparePaths(a[1], b[1]);
  if (byPath !== 0) return byPath < 0 ? -1 : 1;
  if (a[2] !== b[2]) return a[2] ? 1 : -1;
  if (a[3] !== b[3]) return a[3] ? 1 : -1;
  return 0;
}

/** `max(errors, key=relevance)` — Python keeps the first of several maxima. */
function mostRelevant(errors) {
  let best = errors[0];
  for (const error of errors.slice(1)) {
    if (compareRelevance(error, best) > 0) best = error;
  }
  return best;
}

/** `heapq.nsmallest(2, ..., key=relevance)`, which is a stable partial sort. */
function twoLeastRelevant(errors) {
  return errors
    .map((error, index) => ({ error, index }))
    .sort((a, b) => compareRelevance(a.error, b.error) || a.index - b.index)
    .slice(0, 2)
    .map((entry) => entry.error);
}

/**
 * `best_match()` — pick the most relevant top level error, then descend into its
 * sub-errors as long as one of them stands out from its siblings.
 */
export function bestMatch(errors) {
  if (errors.length === 0) return undefined;
  let best = mostRelevant(errors);
  while (best.context.length > 0) {
    const smallest = twoLeastRelevant(best.context);
    if (smallest.length === 2 && compareRelevance(smallest[0], smallest[1]) === 0) return best;
    [best] = smallest;
  }
  return best;
}

