/**
 * `jsonschema._types` — the per-draft `TYPE_CHECKER`s.
 *
 * Note that `bool` is a subclass of `int` in Python, so every checker has to
 * exclude booleans from the numeric types explicitly, and that from draft 6
 * onwards a float with no fractional part counts as an "integer".
 */

import { isBool, isDict, isFloat, isInt, isIntegral, isList, isNone, isNumber, isStr } from './pyvalue.mjs';

const COMMON = {
  null: isNone,
  boolean: isBool,
  string: isStr,
  object: isDict,
  array: isList,
  number: (value) => isNumber(value),
};

/** draft 3 and 4: only a real `int` is an integer. */
export const STRICT_INTEGER_TYPES = {
  ...COMMON,
  integer: (value) => isInt(value),
};

/** draft 6 and later: `1.0` is an integer too. */
export const LENIENT_INTEGER_TYPES = {
  ...COMMON,
  integer: (value) => isInt(value) || (isFloat(value) && isIntegral(value)),
};

export const DRAFT3_TYPES = {
  ...STRICT_INTEGER_TYPES,
  any: () => true,
};

/** `validator.is_type(instance, type)`; an unknown type name is a schema error. */
export function makeTypeChecker(definitions) {
  return (instance, typeName) => {
    const check = definitions[typeName];
    return check === undefined ? false : check(instance);
  };
}

export function knowsType(definitions, typeName) {
  return Object.prototype.hasOwnProperty.call(definitions, typeName);
}

