/**
 * Minimal RFC 3986 reference resolution.
 *
 * `$id` and `$ref` are URI references, and the base of a schema document with no
 * `$id` is the empty string, which `new URL()` cannot represent — hence the
 * hand-rolled implementation.
 */

const ABSOLUTE = /^([A-Za-z][A-Za-z0-9+.-]*):(.*)$/;

function split(uri) {
  const parts = { scheme: '', authority: null, path: '', query: null, fragment: null };
  let rest = uri;

  const hash = rest.indexOf('#');
  if (hash !== -1) {
    parts.fragment = rest.slice(hash + 1);
    rest = rest.slice(0, hash);
  }
  const question = rest.indexOf('?');
  if (question !== -1) {
    parts.query = rest.slice(question + 1);
    rest = rest.slice(0, question);
  }
  const absolute = ABSOLUTE.exec(rest);
  if (absolute) {
    [, parts.scheme] = absolute;
    rest = absolute[2];
  }
  if (rest.startsWith('//')) {
    const end = rest.indexOf('/', 2);
    parts.authority = end === -1 ? rest.slice(2) : rest.slice(2, end);
    rest = end === -1 ? '' : rest.slice(end);
  }
  parts.path = rest;
  return parts;
}

function join(parts) {
  let out = parts.scheme ? `${parts.scheme}:` : '';
  if (parts.authority !== null) out += `//${parts.authority}`;
  out += parts.path;
