/**
 * The `referencing` registry/resolver pair, reduced to what a single in-memory
 * schema document (plus the bundled metaschemas) needs.
 *
 * A document is crawled once up front so that every `$id`, `$anchor` and
 * `$dynamicAnchor` it declares is known before validation starts, and so that
 * each subschema remembers the base URI it lives under.
 */

import { UnresolvableRefError } from './errors.mjs';
import { isDict, isList, isStr } from './pyvalue.mjs';
import { defragment, percentDecode, resolveUri, unescapePointerToken } from './uri.mjs';

export class Registry {
  constructor() {
    this.resources = new Map();
    this.anchors = new Map();
    this.bases = new Map();
  }

  addResource(uri, contents) {
    if (!this.resources.has(uri)) this.resources.set(uri, contents);
  }

  addAnchor(uri, name, contents, dynamic) {
    if (!this.anchors.has(uri)) this.anchors.set(uri, new Map());
    const table = this.anchors.get(uri);
    if (!table.has(name)) table.set(name, { contents, dynamic });
  }

  anchor(uri, name) {
    return this.anchors.get(uri)?.get(name);
  }

  baseOf(contents, fallback) {
    return this.bases.get(contents) ?? fallback;
  }

  /** Walk a schema document, recording identifiers and anchors as we go. */
  crawl(contents, baseUri, spec) {
    if (!isDict(contents)) return;

    let base = baseUri;
    const id = contents.get(spec.idKeyword);
    if (isStr(id) && id !== '' && !(spec.legacyId && id.startsWith('#'))) {
      base = defragment(resolveUri(base, id)).base;
      this.addResource(base, contents);
    } else if (spec.legacyId && isStr(id) && id.startsWith('#')) {
      this.addAnchor(base, id.slice(1), contents, false);
    }
    if (!this.bases.has(contents)) this.bases.set(contents, base);

    const anchor = contents.get(spec.anchorKeyword);
    if (isStr(anchor)) this.addAnchor(base, anchor, contents, false);
    const dynamicAnchor = contents.get(spec.dynamicAnchorKeyword);
    if (isStr(dynamicAnchor)) this.addAnchor(base, dynamicAnchor, contents, true);
    if (contents.get(spec.recursiveAnchorKeyword) === true) {
      this.addAnchor(base, '', contents, true);
    }

    for (const keyword of spec.schemaKeywords) {
      if (contents.has(keyword)) this.crawl(contents.get(keyword), base, spec);
    }
    for (const keyword of spec.schemaArrayKeywords) {
      const value = contents.get(keyword);
      if (isList(value)) for (const item of value) this.crawl(item, base, spec);
    }
    for (const keyword of spec.schemaMapKeywords) {
      const value = contents.get(keyword);
      if (isDict(value)) for (const item of value.values()) this.crawl(item, base, spec);
    }
    for (const keyword of spec.schemaOrArrayKeywords) {
      const value = contents.get(keyword);
      if (isList(value)) for (const item of value) this.crawl(item, base, spec);
      else if (value !== undefined) this.crawl(value, base, spec);
    }
    for (const keyword of spec.schemaOrArrayMapKeywords) {
      const value = contents.get(keyword);
      if (isDict(value)) for (const item of value.values()) if (!isList(item)) this.crawl(item, base, spec);
    }
  }
}

export class Resolver {
  constructor(registry, baseUri, previous = []) {
    this.registry = registry;
    this.baseUri = baseUri;
    this.previous = previous;
  }

  /** `Resolver.in_subresource` — only an `$id` changes the base URI. */
  inSubresource(schema, spec) {
    if (!isDict(schema)) return this;
    const id = schema.get(spec.idKeyword);
    if (!isStr(id) || id === '' || (spec.legacyId && id.startsWith('#'))) return this;
    return new Resolver(this.registry, defragment(resolveUri(this.baseUri, id)).base, this.previous);
  }

  descendant(contents, uri) {
    const base = this.registry.baseOf(contents, uri);
    return new Resolver(this.registry, base, [this.baseUri, ...this.previous]);
  }

  lookup(ref) {
    const [uri, fragment] = ref.startsWith('#')
      ? [this.baseUri, ref.slice(1)]
      : (({ base, fragment: f }) => [base, f])(defragment(resolveUri(this.baseUri, ref)));

    if (fragment === '' || fragment.startsWith('/')) {
      const resource = this.resources(uri, ref);
      const contents = pointer(resource, fragment, ref);
      return { contents, resolver: this.descendant(contents, uri) };
    }

    const name = percentDecode(fragment);
    const found = this.registry.anchor(uri, name);
    if (found === undefined) {
      this.resources(uri, ref);
      throw new UnresolvableRefError(ref);
    }
    if (!found.dynamic) {
      return { contents: found.contents, resolver: this.descendant(found.contents, uri) };
    }
    return this.resolveDynamic(name, found.contents, uri);
  }

  /**
   * `DynamicAnchor.resolve` — the outermost enclosing scope that declares the
   * same `$dynamicAnchor` wins over the statically located one.
   */
  resolveDynamic(name, staticContents, uri) {
    let contents = staticContents;
    let base = uri;
    for (const scope of this.previous) {
      const candidate = this.registry.anchor(scope, name);
      if (candidate !== undefined && candidate.dynamic) {
        contents = candidate.contents;
        base = scope;
      }
    }
    return { contents, resolver: this.descendant(contents, base) };
  }

  resources(uri, ref) {
    const resource = this.registry.resources.get(uri);
    if (resource === undefined) throw new UnresolvableRefError(ref);
    return resource;
  }
}

function pointer(document, fragment, ref) {
  let target = document;
  if (fragment === '') return target;
  for (const rawToken of percentDecode(fragment).slice(1).split('/')) {
    if (isList(target)) {
      const index = Number(rawToken);
      if (!Number.isInteger(index) || index < 0 || index >= target.length) {
        throw new UnresolvableRefError(ref);
      }
      target = target[index];
    } else if (isDict(target)) {
      const token = unescapePointerToken(rawToken);
      if (!target.has(token)) throw new UnresolvableRefError(ref);
      target = target.get(token);
    } else {
      throw new UnresolvableRefError(ref);
    }
  }
  return target;
}

