/**
 * The assertion vocabulary: keywords that inspect an instance directly rather
 * than applying subschemas to it.
 */

import { ValidationError } from '../errors.mjs';
import { repr } from '../pyrepr.mjs';
import { search } from '../pyregex.mjs';
import { strLen } from '../pystr.mjs';
import { equal, isDict, isFloat, isInt, isList, isStr, toFloat, uniq } from '../pyvalue.mjs';

/** `_utils.ensure_list` — a bare string stands for a one element list. */
function ensureList(value) {
  return isStr(value) ? [value] : value;
}

export function* type(validator, types, instance) {
  const wanted = ensureList(types);
  if (wanted.some((each) => validator.isType(instance, each))) return;
  yield new ValidationError(`${repr(instance)} is not of type ${wanted.map(repr).join(', ')}`);
}

export function* enum_(validator, enums, instance) {
  if (enums.every((each) => !equal(each, instance))) {
    yield new ValidationError(`${repr(instance)} is not one of ${repr(enums)}`);
  }
}

export function* const_(validator, constant, instance) {
  if (!equal(instance, constant)) {
    yield new ValidationError(`${repr(constant)} was expected`);
  }
}

export function* minimum(validator, bound, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (instance < bound) {
    yield new ValidationError(`${repr(instance)} is less than the minimum of ${repr(bound)}`);
  }
}

export function* maximum(validator, bound, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (instance > bound) {
    yield new ValidationError(`${repr(instance)} is greater than the maximum of ${repr(bound)}`);
  }
}

export function* exclusiveMinimum(validator, bound, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (instance <= bound) {
    yield new ValidationError(
      `${repr(instance)} is less than or equal to the minimum of ${repr(bound)}`,
    );
  }
}

export function* exclusiveMaximum(validator, bound, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (instance >= bound) {
    yield new ValidationError(
      `${repr(instance)} is greater than or equal to the maximum of ${repr(bound)}`,
    );
  }
}

/**
 * A float divisor is checked through division so that e.g. 1.5 is a multiple of
 * 0.5; an integer divisor uses the remainder operator, as CPython does.
 */
function isNotMultipleOf(instance, divisor) {
  if (isFloat(divisor)) {
    const quotient = toFloat(instance) / divisor;
    if (!Number.isFinite(quotient)) return true;
    return Math.trunc(quotient) !== quotient;
  }
  if (isInt(instance)) return instance % divisor !== 0n;
  return toFloat(instance) % Number(divisor) !== 0;
}

export function* multipleOf(validator, divisor, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (isNotMultipleOf(instance, divisor)) {
    yield new ValidationError(`${repr(instance)} is not a multiple of ${repr(divisor)}`);
  }
}

export function* minItems(validator, limit, instance) {
  if (!validator.isType(instance, 'array') || instance.length >= limit) return;
  const message = limit === 1n ? 'should be non-empty' : 'is too short';
  yield new ValidationError(`${repr(instance)} ${message}`);
}

export function* maxItems(validator, limit, instance) {
  if (!validator.isType(instance, 'array') || instance.length <= limit) return;
  const message = limit === 0n ? 'is expected to be empty' : 'is too long';
  yield new ValidationError(`${repr(instance)} ${message}`);
}

export function* minLength(validator, limit, instance) {
  if (!validator.isType(instance, 'string') || strLen(instance) >= limit) return;
  const message = limit === 1n ? 'should be non-empty' : 'is too short';
  yield new ValidationError(`${repr(instance)} ${message}`);
}

export function* maxLength(validator, limit, instance) {
  if (!validator.isType(instance, 'string') || strLen(instance) <= limit) return;
  const message = limit === 0n ? 'is expected to be empty' : 'is too long';
  yield new ValidationError(`${repr(instance)} ${message}`);
}

export function* minProperties(validator, limit, instance) {
  if (!validator.isType(instance, 'object') || instance.size >= limit) return;
  const message = limit === 1n ? 'should be non-empty' : 'does not have enough properties';
  yield new ValidationError(`${repr(instance)} ${message}`);
}

export function* maxProperties(validator, limit, instance) {
  if (!validator.isType(instance, 'object') || instance.size <= limit) return;
  const message = limit === 0n ? 'is expected to be empty' : 'has too many properties';
  yield new ValidationError(`${repr(instance)} ${message}`);
}

export function* uniqueItems(validator, unique, instance) {
  if (!unique || !validator.isType(instance, 'array')) return;
  if (!uniq(instance)) {
    yield new ValidationError(`${repr(instance)} has non-unique elements`);
  }
}

export function* pattern(validator, expression, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (!search(expression, instance)) {
    yield new ValidationError(`${repr(instance)} does not match ${repr(expression)}`);
  }
}

export function* required(validator, properties, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of properties) {
    if (!instance.has(property)) {
      yield new ValidationError(`${repr(property)} is a required property`);
    }
  }
}

export function* dependentRequired(validator, dependencies, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, dependency] of dependencies) {
    if (!instance.has(property)) continue;
    for (const each of dependency) {
      if (!instance.has(each)) {
        yield new ValidationError(`${repr(each)} is a dependency of ${repr(property)}`);
      }
    }
  }
}

/**
 * `format` is only asserted when a format checker is attached, which
 * `validate()` never does for the instance but `check_schema()` does for the
 * metaschema.
 */
export function* format(validator, wanted, instance) {
