  if (!validator.isType(instance, 'object')) return;
  for (const property of instance.keys()) {
    yield* validator.descend(property, subschema);
  }
}

export function* prefixItems(validator, subschemas, instance) {
  if (!validator.isType(instance, 'array')) return;
  const shared = Math.min(subschemas.length, instance.length);
  for (let index = 0; index < shared; index += 1) {
    yield* validator.descend(instance[index], subschemas[index], {
      path: BigInt(index),
      schemaPath: BigInt(index),
