/**
 * `unevaluatedItems` / `unevaluatedProperties`.
 *
 * Both keywords need to know which parts of the instance the *sibling* keywords
 * already applied a subschema to, so each one first collects the set of
 * evaluated locations by walking the schema's applicators.
 */

import { ValidationError } from '../errors.mjs';
import { extrasMsg } from '../pyrepr.mjs';
import { search } from '../pyregex.mjs';
import { sortStrings } from '../pystr.mjs';
import { isDict, isList } from '../pyvalue.mjs';

/** Follow `$ref`/`$dynamicRef` and report the evaluated locations behind it. */
function throughReferences(validator, instance, schema, collect) {
  const found = [];
  for (const keyword of ['$ref', '$dynamicRef']) {
    if (!schema.has(keyword)) continue;
    let resolved;
    try {
      resolved = validator.lookup(schema.get(keyword));
    } catch {
      continue;
    }
    const evolved = validator.evolve(resolved.contents, resolved.resolver);
    found.push(...collect(evolved, instance, resolved.contents));
  }
  return found;
}

/** Subschemas whose annotations count: every `allOf`, the successful `*Of` branches. */
function* applicableBranches(validator, instance, schema) {
  const allOf = schema.get('allOf');
  if (isList(allOf)) yield* allOf;

  for (const keyword of ['anyOf', 'oneOf']) {
    const branches = schema.get(keyword);
    if (!isList(branches)) continue;
    for (const branch of branches) {
      if (validator.isValid(instance, branch)) yield branch;
    }
  }

  if (schema.has('if')) {
    const condition = schema.get('if');
    if (validator.isValid(instance, condition)) {
      yield condition;
      if (schema.has('then')) yield schema.get('then');
    } else if (schema.has('else')) {
      yield schema.get('else');
    }
  }
}

/** `_utils.find_evaluated_property_keys_by_schema` */
export function findEvaluatedPropertyKeys(validator, instance, schema) {
  if (!isDict(schema)) return [];
  const keys = [...throughReferences(validator, instance, schema, findEvaluatedPropertyKeys)];

  for (const keyword of ['additionalProperties', 'unevaluatedProperties']) {
    if (schema.get(keyword) !== false && schema.has(keyword)) keys.push(...instance.keys());
  }

  const properties = schema.get('properties');
  if (isDict(properties)) {
    for (const property of properties.keys()) {
      if (instance.has(property)) keys.push(property);
    }
  }

  const patternProperties = schema.get('patternProperties');
  if (isDict(patternProperties)) {
    for (const expression of patternProperties.keys()) {
      for (const property of instance.keys()) {
        if (search(expression, property)) keys.push(property);
      }
    }
  }

  const dependentSchemas = schema.get('dependentSchemas');
  if (isDict(dependentSchemas)) {
    for (const [property, subschema] of dependentSchemas) {
      if (!instance.has(property)) continue;
      keys.push(...findEvaluatedPropertyKeys(validator, instance, subschema));
    }
  }

  for (const branch of applicableBranches(validator, instance, schema)) {
    keys.push(...findEvaluatedPropertyKeys(validator, instance, branch));
  }
  return keys;
}

/** `_utils.find_evaluated_item_indexes_by_schema` */
export function findEvaluatedItemIndexes(validator, instance, schema) {
  if (!isDict(schema)) return [];
  const indexes = [...throughReferences(validator, instance, schema, findEvaluatedItemIndexes)];

  const prefix = schema.get('prefixItems');
  if (isList(prefix)) {
    for (let index = 0; index < Math.min(prefix.length, instance.length); index += 1) {
      indexes.push(index);
    }
  }

  for (const keyword of ['items', 'additionalItems', 'unevaluatedItems']) {
    const value = schema.get(keyword);
    if (value === false || value === undefined) continue;
    if (keyword === 'items' && isList(value)) {
      for (let index = 0; index < Math.min(value.length, instance.length); index += 1) {
        indexes.push(index);
      }
      continue;
    }
    for (let index = 0; index < instance.length; index += 1) indexes.push(index);
  }

  const containsSchema = schema.get('contains');
  if (containsSchema !== undefined) {
    for (let index = 0; index < instance.length; index += 1) {
      if (validator.isValid(instance[index], containsSchema)) indexes.push(index);
    }
  }

  for (const branch of applicableBranches(validator, instance, schema)) {
    indexes.push(...findEvaluatedItemIndexes(validator, instance, branch));
  }
  return indexes;
}

export function* unevaluatedItems(validator, subschema, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const evaluated = new Set(findEvaluatedItemIndexes(validator, instance, schema));
  const offending = [];
  for (let index = 0; index < instance.length; index += 1) {
    if (evaluated.has(index)) continue;
    for (const _ of validator.descend(instance[index], subschema, { path: BigInt(index) })) {
      offending.push(instance[index]);
      break;
    }
  }
  if (offending.length === 0) return;
  const { joined, verb } = extrasMsg(offending);
  yield new ValidationError(`Unevaluated items are not allowed (${joined} ${verb} unexpected)`);
}

export function* unevaluatedProperties(validator, subschema, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  const evaluated = new Set(findEvaluatedPropertyKeys(validator, instance, schema));
  const offending = [];
  for (const [property, value] of instance) {
    if (evaluated.has(property)) continue;
    for (const _ of validator.descend(value, subschema, {
      path: property,
      schemaPath: property,
    })) {
      offending.push(property);
      break;
    }
  }
  if (offending.length === 0) return;

  if (subschema === false) {
    const { joined, verb } = extrasMsg(sortStrings(offending));
    yield new ValidationError(
      `Unevaluated properties are not allowed (${joined} ${verb} unexpected)`,
    );
    return;
  }
  const { joined, verb } = extrasMsg(offending);
  yield new ValidationError(
    `Unevaluated properties are not valid under the given schema (${joined} ${verb} unevaluated and invalid)`,
  );
}

