 * Keyword spellings that only exist in the older drafts: the array form of
 * `items` with `additionalItems`, `dependencies` before it split into
 * `dependentRequired`/`dependentSchemas`, and the draft 3 oddities.
 */

import { ValidationError } from '../errors.mjs';
import { extrasMsg, repr } from '../pyrepr.mjs';
import { isDict, isList, isStr } from '../pyvalue.mjs';

function ensureList(value) {
  return isStr(value) ? [value] : value;
}

/** draft 6 / 7 / 2019-09 `items`: a schema, or one schema per position. */
export function* itemsLegacy(validator, subschema, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (isList(subschema)) {
    const shared = Math.min(subschema.length, instance.length);
    for (let index = 0; index < shared; index += 1) {
      yield* validator.descend(instance[index], subschema[index], {
        path: BigInt(index),
        schemaPath: BigInt(index),
      });
    }
    return;
  }
  for (let index = 0; index < instance.length; index += 1) {
    yield* validator.descend(instance[index], subschema, { path: BigInt(index) });
  }
}

/** draft 3 / 4 `items` — the same, minus the `schema_path` on the tuple form. */
export function* itemsDraft3Draft4(validator, subschema, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (isList(subschema)) {
    const shared = Math.min(subschema.length, instance.length);
    for (let index = 0; index < shared; index += 1) {
      yield* validator.descend(instance[index], subschema[index], { path: BigInt(index) });
    }
    return;
  }
  for (let index = 0; index < instance.length; index += 1) {
    yield* validator.descend(instance[index], subschema, { path: BigInt(index) });
  }
}

export function* additionalItems(validator, subschema, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  // `additionalItems` is meaningless when `items` is a single schema.
  if (validator.isType(schema.get('items'), 'object')) return;
  const positional = isList(schema.get('items')) ? schema.get('items').length : 0;

  if (validator.isType(subschema, 'object')) {
    for (let index = positional; index < instance.length; index += 1) {
      yield* validator.descend(instance[index], subschema, { path: BigInt(index) });
    }
    return;
  }
  if (subschema !== false || instance.length <= positional) return;
  const { joined, verb } = extrasMsg(instance.slice(positional));
  yield new ValidationError(`Additional items are not allowed (${joined} ${verb} unexpected)`);
