  if (!validator.isType(instance, 'object')) return;
  for (const [property, dependency] of dependencyMap) {
    if (!instance.has(property)) continue;
    if (validator.isType(dependency, 'object')) {
      yield* validator.descend(instance, dependency, { schemaPath: property });
    } else if (validator.isType(dependency, 'string')) {
      if (!instance.has(dependency)) {
        yield new ValidationError(`${repr(dependency)} is a dependency of ${repr(property)}`);
      }
    } else {
      for (const each of dependency) {
        if (!instance.has(each)) {
