export function* typeDraft3(validator, types, instance) {
  const wanted = ensureList(types);
  const allErrors = [];
  for (let index = 0; index < wanted.length; index += 1) {
    const candidate = wanted[index];
    if (validator.isType(candidate, 'object')) {
