  if (validator.isType(extendsValue, 'object')) {
    yield* validator.descend(instance, extendsValue);
    return;
  }
  for (let index = 0; index < extendsValue.length; index += 1) {
    yield* validator.descend(instance, extendsValue[index], { schemaPath: BigInt(index) });
  }
}

