/**
 * Positions that hold subschemas, used when crawling a document for `$id`s and
 * anchors. A superset across drafts is harmless: a keyword that does not exist
 * in a given draft cannot appear in a schema that draft accepts.
 */
function subresourceSpec({ idKeyword, legacyId = false, anchorKeyword = null, dynamicAnchorKeyword = null, recursiveAnchorKeyword = null }) {
  return {
    idKeyword,
    legacyId,
    anchorKeyword,
    dynamicAnchorKeyword,
    recursiveAnchorKeyword,
    schemaKeywords: [
      'additionalItems', 'additionalProperties', 'contains', 'contentSchema', 'else', 'if',
      'not', 'propertyNames', 'then', 'unevaluatedItems', 'unevaluatedProperties',
    ],
    schemaArrayKeywords: ['allOf', 'anyOf', 'oneOf', 'prefixItems'],
    schemaMapKeywords: ['$defs', 'definitions', 'dependentSchemas', 'patternProperties', 'properties'],
    schemaOrArrayKeywords: ['items', 'extends'],
    schemaOrArrayMapKeywords: ['dependencies'],
  };
}

