/**
 * The applicator vocabulary: keywords that apply subschemas to an instance or to
 * parts of it.
 */

import { ValidationError } from '../errors.mjs';
import { extrasMsg, repr } from '../pyrepr.mjs';
import { search } from '../pyregex.mjs';
import { sortStrings } from '../pystr.mjs';
import { isDict, isList } from '../pyvalue.mjs';

/** `_utils.find_additional_properties` — instance keys `properties`/`patternProperties` miss. */
function* findAdditionalProperties(instance, schema) {
  const properties = schema.get('properties');
  const patternProperties = schema.get('patternProperties');
  // CPython joins the patterns with `|` and searches once.
  const patterns = isDict(patternProperties) ? [...patternProperties.keys()].join('|') : '';
  for (const property of instance.keys()) {
    if (isDict(properties) && properties.has(property)) continue;
    if (patterns !== '' && search(patterns, property)) continue;
    yield property;
  }
}

export function* additionalProperties(validator, subschema, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  const extras = [...findAdditionalProperties(instance, schema)];

  if (validator.isType(subschema, 'object')) {
    for (const extra of extras) {
      yield* validator.descend(instance.get(extra), subschema, { path: extra });
    }
    return;
  }
  if (subschema !== false || extras.length === 0) return;

  if (schema.has('patternProperties')) {
    const verb = extras.length === 1 ? 'does' : 'do';
    const joined = sortStrings(extras).map(repr).join(', ');
    const patterns = sortStrings([...schema.get('patternProperties').keys()]).map(repr).join(', ');
    yield new ValidationError(`${joined} ${verb} not match any of the regexes: ${patterns}`);
    return;
  }
  const { joined, verb } = extrasMsg(sortStrings(extras));
  yield new ValidationError(`Additional properties are not allowed (${joined} ${verb} unexpected)`);
}

export function* properties(validator, subschemas, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, subschema] of subschemas) {
    if (instance.has(property)) {
      yield* validator.descend(instance.get(property), subschema, {
        path: property,
        schemaPath: property,
      });
    }
  }
}

export function* patternProperties(validator, subschemas, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [expression, subschema] of subschemas) {
    for (const [key, value] of instance) {
