/** 2020-12 `items` — everything past `prefixItems`. */
export function* items(validator, subschema, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const prefix = isList(schema.get('prefixItems')) ? schema.get('prefixItems').length : 0;
  const total = instance.length;
  const extra = total - prefix;
  if (extra <= 0) return;

  if (subschema === false) {
    const rest = extra !== 1 ? instance.slice(prefix) : instance[prefix];
    const noun = prefix !== 1 ? 'items' : 'item';
    yield new ValidationError(
      `Expected at most ${prefix} ${noun} but found ${extra} extra: ${repr(rest)}`,
    );
    return;
