export function* contains(validator, subschema, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const minContains = schema.has('minContains') ? Number(schema.get('minContains')) : 1;
  const maxContains = schema.has('maxContains') ? Number(schema.get('maxContains')) : instance.length;

  let matches = 0;
  for (const each of instance) {
    if (validator.isValid(each, subschema)) {
      matches += 1;
      if (matches > maxContains) {
        yield new ValidationError(
          `Too many items match the given schema (expected at most ${repr(schema.get('maxContains'))})`,
          { validator: 'maxContains' },
        );
        return;
      }
    }
  }
  if (matches >= minContains) return;
  if (matches === 0) {
    yield new ValidationError(`${repr(instance)} does not contain items matching the given schema`);
    return;
  }
  yield new ValidationError(
    `Too few items match the given schema (expected at least ${repr(schema.get('minContains'))} but only ${matches} matched)`,
    { validator: 'minContains' },
  );
