export function* allOf(validator, subschemas, instance) {
  for (let index = 0; index < subschemas.length; index += 1) {
    yield* validator.descend(instance, subschemas[index], { schemaPath: BigInt(index) });
  }
}

export function* anyOf(validator, subschemas, instance) {
  const allErrors = [];
  for (let index = 0; index < subschemas.length; index += 1) {
    const errors = [...validator.descend(instance, subschemas[index], { schemaPath: BigInt(index) })];
    if (errors.length === 0) return;
    allErrors.push(...errors);
  }
  yield new ValidationError(`${repr(instance)} is not valid under any of the given schemas`, {
    context: allErrors,
  });
}

export function* oneOf(validator, subschemas, instance) {
  const allErrors = [];
  let firstValid;
  let index = 0;
  for (; index < subschemas.length; index += 1) {
    const errors = [...validator.descend(instance, subschemas[index], { schemaPath: BigInt(index) })];
    if (errors.length === 0) {
      firstValid = subschemas[index];
      break;
    }
    allErrors.push(...errors);
  }
  if (firstValid === undefined) {
    yield new ValidationError(`${repr(instance)} is not valid under any of the given schemas`, {
      context: allErrors,
    });
    return;
  }

  // The enumeration continues where the first pass stopped, so the extra matches
  // are reported before the one that matched first.
  const moreMatches = subschemas
    .slice(index + 1)
    .filter((subschema) => validator.isValid(instance, subschema));
  if (moreMatches.length === 0) return;
  const reprs = [...moreMatches, firstValid].map(repr).join(', ');
  yield new ValidationError(`${repr(instance)} is valid under each of ${reprs}`);
}

export function* not(validator, subschema, instance) {
  if (validator.isValid(instance, subschema)) {
    yield new ValidationError(`${repr(instance)} should not be valid under ${repr(subschema)}`);
  }
}

export function* if_(validator, condition, instance, schema) {
  if (validator.isValid(instance, condition)) {
    if (schema.has('then')) {
      yield* validator.descend(instance, schema.get('then'), { schemaPath: 'then' });
    }
    return;
  }
  if (schema.has('else')) {
    yield* validator.descend(instance, schema.get('else'), { schemaPath: 'else' });
  }
}

export function* ref(validator, reference, instance) {
  const resolved = validator.lookup(reference);
  yield* validator.descend(instance, resolved.contents, { resolver: resolved.resolver });
}

export const dynamicRef = ref;

/** 2019-09 `$recursiveRef` always points at the outermost `$recursiveAnchor`. */
export function* recursiveRef(validator, reference, instance) {
  const resolved = validator.lookupRecursive();
  yield* validator.descend(instance, resolved.contents, { resolver: resolved.resolver });
}

