/**
 * `jsonschema.validators` — the validator object, `validator_for`,
 * `check_schema` and `validate`.
 */

import { ALL_DRAFTS, BY_META_SCHEMA_ID, LATEST } from './drafts.mjs';
import { SchemaError, ValidationError, bestMatch } from './errors.mjs';
import { repr } from './pyrepr.mjs';
import { isValidPattern } from './pyregex.mjs';
import { Registry, Resolver } from './refs.mjs';
import { fromPlain, isDict, isStr } from './pyvalue.mjs';
import { makeTypeChecker } from './typechecker.mjs';

/**
 * `check_schema` attaches the draft's format checker. Only the checks backed by
 * the standard library are actually active in a default install, and of those
 * the metaschemas only ever use "regex".
 */
const SCHEMA_FORMAT_CHECKER = { regex: isValidPattern };

class Validator {
  constructor(draft, schema, resolver, formatChecker) {
    this.draft = draft;
    this.schema = schema;
    this.resolver = resolver;
    this.formatChecker = formatChecker;
    this.isTypeChecked = makeTypeChecker(draft.types);
  }

  isType(instance, typeName) {
    return isStr(typeName) ? this.isTypeChecked(instance, typeName) : false;
  }

  /** `evolve()` re-selects the draft when the subschema declares its own `$schema`. */
  evolve(schema, resolver) {
    const draft = validatorFor(schema, this.draft);
    return new Validator(draft, schema, resolver ?? this.resolver, this.formatChecker);
  }

  /** `applicable_validators` — drafts up to 7 let `$ref` suppress its siblings. */
  *applicable() {
    if (this.draft.ignoreRefSiblings && this.schema.has('$ref')) {
      yield ['$ref', this.schema.get('$ref')];
      return;
    }
    yield* this.schema;
  }

  *iterErrors(instance) {
    if (this.schema === true) return;
    if (this.schema === false) {
      yield new ValidationError(`False schema does not allow ${repr(instance)}`, {
        validator: null,
      });
      return;
    }
    for (const [keyword, value] of this.applicable()) {
      const keywordValidator = this.draft.keywords[keyword];
      if (keywordValidator === undefined) continue;
      for (const error of keywordValidator(this, value, instance, this.schema)) {
        error.setValidator(keyword);
        yield error;
      }
    }
  }

  *descend(instance, schema, { path, resolver } = {}) {
    const nested = resolver ?? this.resolver.inSubresource(schema, this.draft.spec);
    for (const error of this.evolve(schema, nested).iterErrors(instance)) {
      if (path !== undefined) error.path.unshift(path);
      yield error;
    }
  }

  isValid(instance, schema) {
    const target = schema === undefined ? this : this.evolve(schema, this.resolver);
    // eslint-disable-next-line no-unused-vars
    for (const error of target.iterErrors(instance)) return false;
    return true;
  }

  lookup(ref) {
    return this.resolver.lookup(ref);
  }

  /** `lookup_recursive_ref` — `$recursiveRef` follows `$recursiveAnchor` outwards. */
  lookupRecursive() {
    const resolved = this.resolver.lookup('#');
    if (isDict(resolved.contents) && resolved.contents.get('$recursiveAnchor') === true) {
      return this.resolver.resolveDynamic('', resolved.contents, this.resolver.baseUri);
    }
    return resolved;
  }
}

/** `validator_for(schema, default)` */
export function validatorFor(schema, fallback = LATEST) {
  if (!isDict(schema)) return fallback;
  const declared = schema.get('$schema');
  if (!isStr(declared)) return fallback;
  return BY_META_SCHEMA_ID.get(declared) ?? fallback;
}

let specifications = null;

/** Every bundled metaschema document, crawled once and shared. */
function specificationDocuments() {
  if (specifications === null) {
    specifications = [];
    for (const draft of ALL_DRAFTS) {
      for (const document of draft.documents) {
        specifications.push({ contents: fromPlain(document), spec: draft.spec });
      }
    }
  }
  return specifications;
}

function buildRegistry(rootContents, draft) {
  const registry = new Registry();
  const rootBase = '';
  registry.addResource(rootBase, rootContents);
  registry.crawl(rootContents, rootBase, draft.spec);
  for (const { contents, spec } of specificationDocuments()) {
    registry.crawl(contents, '', spec);
  }
  return { registry, resolver: new Resolver(registry, registry.baseOf(rootContents, rootBase)) };
}

function metaValidatorFor(draft) {
  if (draft.metaValidator === undefined) {
    const contents = fromPlain(draft.metaSchema);
    const { registry, resolver } = buildRegistry(contents, draft);
    draft.metaValidator = new Validator(draft, contents, resolver, SCHEMA_FORMAT_CHECKER);
    void registry;
  }
  return draft.metaValidator;
}

/** `Validator.check_schema` — raises on the *first* metaschema error it finds. */
export function checkSchema(schema, draft) {
  for (const error of metaValidatorFor(draft).iterErrors(schema)) {
    throw new SchemaError(error.pyMessage);
  }
}

/**
 * `jsonschema.validate(instance, schema)`: check the schema, collect every
 * error, then raise the single best match.
 */
export function validate(instance, schema) {
  const draft = validatorFor(schema);
  checkSchema(schema, draft);
  const { resolver } = buildRegistry(schema, draft);
  const validator = new Validator(draft, schema, resolver, null);
  const error = bestMatch([...validator.iterErrors(instance)]);
  if (error !== undefined) throw error;
}

